#!/usr/bin/env bun
/**
 * Propagate the single source of truth for the plugin's own metadata.
 *
 * `package.json` owns the version (CalVer, `YYYY.M.MICRO`, matching signage-kit) and
 * the WordPress support floor. Everything else is derived:
 *
 *   - the `Version:` plugin header, which is what WordPress shows and compares
 *   - the `SRLY_VERSION` constant, used to cache-bust enqueued assets
 *   - the `Requires at least:` and `Requires PHP:` headers, which WordPress enforces
 *     before it will activate the plugin
 *
 * readme.txt is not in that list any more: it is generated by `bun run readme`, which
 * writes the stable tag and the same two support fields from these values. A
 * generated file cannot drift, so there is nothing left there to check.
 *
 * Run with `--check` to verify without writing; CI uses that to refuse a release
 * whose git tag and plugin header disagree.
 *
 * The constant matters more than it looks. It previously shipped as the literal
 * string `VERSION_PLACEHOLDER` (nothing ever substituted it), so every release
 * enqueued its CSS and JS under the same version and signage players happily
 * served stale assets after an update.
 */

import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, relative } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = dirname(dirname(fileURLToPath(import.meta.url)))
const PLUGIN_FILE = join(ROOT, 'screenly-cast/screenly-cast.php')
const PACKAGE_FILE = join(ROOT, 'package.json')

/** CalVer: four-digit year, unpadded month, micro. */
const CALVER = /^\d{4}\.(?:[1-9]|1[0-2])\.\d+$/

type Rule = {
  file: string
  label: string
  pattern: RegExp
  /** The value this field must hold, and the replacement that writes it. */
  value: (meta: Meta) => string
  replace: (value: string) => string
}

type Meta = {
  version: string
  requiresAtLeast: string
  requiresPHP: string
}

const RULES: Rule[] = [
  {
    file: PLUGIN_FILE,
    label: 'plugin header Version',
    pattern: /^(\s*\*\s*Version:\s*)(.+)$/m,
    value: (meta) => meta.version,
    replace: (v) => `$1${v}`
  },
  {
    file: PLUGIN_FILE,
    label: 'SRLY_VERSION constant',
    pattern: /^(\s*define\(\s*'SRLY_VERSION',\s*')([^']*)('\s*\);)$/m,
    value: (meta) => meta.version,
    replace: (v) => `$1${v}$3`
  },
  {
    file: PLUGIN_FILE,
    label: 'plugin header Requires at least',
    pattern: /^(\s*\*\s*Requires at least:\s*)(.+)$/m,
    value: (meta) => meta.requiresAtLeast,
    replace: (v) => `$1${v}`
  },
  {
    file: PLUGIN_FILE,
    label: 'plugin header Requires PHP',
    pattern: /^(\s*\*\s*Requires PHP:\s*)(.+)$/m,
    value: (meta) => meta.requiresPHP,
    replace: (v) => `$1${v}`
  }
]

function readMeta(): Meta {
  const pkg = JSON.parse(readFileSync(PACKAGE_FILE, 'utf8')) as {
    version?: unknown
    wordpress?: { requiresAtLeast?: unknown; requiresPHP?: unknown }
  }

  const version = pkg.version
  if (typeof version !== 'string' || version === '') {
    throw new Error('package.json has no "version"')
  }
  if (!CALVER.test(version)) {
    throw new Error(
      `Version "${version}" is not CalVer (YYYY.M.MICRO, unpadded month), e.g. 2026.8.0`
    )
  }

  const requiresAtLeast = pkg.wordpress?.requiresAtLeast
  const requiresPHP = pkg.wordpress?.requiresPHP
  if (typeof requiresAtLeast !== 'string' || typeof requiresPHP !== 'string') {
    throw new Error('package.json needs "wordpress.requiresAtLeast" and "wordpress.requiresPHP"')
  }

  return { version, requiresAtLeast, requiresPHP }
}

function main(): number {
  const check = process.argv.includes('--check')
  const meta = readMeta()
  const problems: string[] = []
  const updated: string[] = []

  // Group by file so a file with two rules is read and written once.
  const byFile = new Map<string, Rule[]>()
  for (const rule of RULES) {
    const list = byFile.get(rule.file)
    if (list) {
      list.push(rule)
    } else {
      byFile.set(rule.file, [rule])
    }
  }

  for (const [file, rules] of byFile) {
    const shortName = relative(ROOT, file)
    let contents: string
    try {
      contents = readFileSync(file, 'utf8')
    } catch {
      problems.push(`${shortName}: cannot be read`)
      continue
    }

    let next = contents
    for (const rule of rules) {
      const match = rule.pattern.exec(next)
      if (!match) {
        problems.push(`${shortName}: no ${rule.label} found`)
        continue
      }
      const expected = rule.value(meta)
      const current = match[2]
      if (current === expected) {
        continue
      }
      if (check) {
        problems.push(`${shortName}: ${rule.label} is "${current}", expected "${expected}"`)
        continue
      }
      next = next.replace(rule.pattern, rule.replace(expected))
      updated.push(`${shortName}: ${rule.label} ${current} -> ${expected}`)
    }

    if (!check && next !== contents) {
      writeFileSync(file, next)
    }
  }

  if (problems.length > 0) {
    for (const problem of problems) {
      console.error(`✗ ${problem}`)
    }
    if (check) {
      console.error(`\nRun \`bun run version:sync\` to write version ${meta.version}.`)
    }
    return 1
  }

  if (updated.length === 0) {
    console.log(`Version ${meta.version} is already in sync.`)
  } else {
    for (const line of updated) {
      console.log(`✓ ${line}`)
    }
  }
  return 0
}

process.exit(main())
